### 2. `/assets/functions/terminalCLI/terminal.js`
Crea este archivo con el siguiente contenido completo:

```javascript
/**
 * ==========================================
 * V1R3-SH Terminal CLI Controller
 * Path: /assets/functions/terminalCLI/terminal.js
 * ==========================================
 */

export class TerminalCLI {
  constructor() {
    this.isOpen = false;
    this.commandHistory = [];
    this.historyIndex = -1;
    this.commands = {};
    this.matrixActive = false;
    this.matrixInterval = null;

    this.initDOM();
    this.initCommands();
    this.initEventListeners();
  }

  initDOM() {
    if (document.getElementById('v1r3-terminal-root')) return;

    const root = document.createElement('div');
    root.id = 'v1r3-terminal-root';
    root.innerHTML = `
      <div class="v1r3-terminal-overlay" id="termOverlay" aria-hidden="true" role="dialog" aria-label="v1r3-sh terminal">
        <div class="v1r3-terminal-window">
          <div class="v1r3-terminal-header">
            <div class="v1r3-terminal-title">
              <span class="prompt-symbol">&gt;_</span> v1r3-sh v2.4.0 (x86_64-vire-linux-gnu)
            </div>
            <div class="v1r3-terminal-controls">
              <button class="term-btn close" id="termClose" title="Cerrar"></button>
              <button class="term-btn minimize" id="termMin" title="Minimizar"></button>
              <button class="term-btn maximize" id="termMax" title="Expandir"></button>
            </div>
          </div>
          <div class="v1r3-terminal-body" id="termBody">
            <div class="term-line term-output-info">¡Bienvenido a v1r3-sh! El sandbox interactivo y CLI de Ciberseguridad & Full-Stack.</div>
            <div class="term-line term-output-dim">Escribe <span class="term-output-success">"help"</span> para listar los comandos disponibles o presiona <span class="term-output-success">Tab</span> para autocompletar.</div>
            <br>
          </div>
          <form class="v1r3-terminal-input-form" id="termForm">
            <span class="v1r3-prompt-label">v1r3@dev:~$</span>
            <input type="text" class="v1r3-terminal-input" id="termInput" autocomplete="off" spellcheck="false" autofocus />
          </form>
        </div>
      </div>
    `;
    document.body.appendChild(root);

    this.overlay = document.getElementById('termOverlay');
    this.body = document.getElementById('termBody');
    this.input = document.getElementById('termInput');
    this.form = document.getElementById('termForm');
    this.closeBtn = document.getElementById('termClose');
  }

  initEventListeners() {
    document.addEventListener('click', (e) => {
      if (e.target.closest('.v1r3-sh-trigger') || e.target.closest('[data-action="open-terminal"]')) {
        e.preventDefault();
        this.toggle();
      }
    });

    window.addEventListener('keydown', (e) => {
      if ((e.ctrlKey && e.shiftKey && e.key.toLowerCase() === 't') || (e.key === '`' && document.activeElement.tagName !== 'INPUT' && document.activeElement.tagName !== 'TEXTAREA')) {
        e.preventDefault();
        this.toggle();
      }

      if (this.isOpen) {
        if (e.key === 'Escape') {
          this.close();
        } else if (e.key === 'ArrowUp') {
          e.preventDefault();
          this.navigateHistory('up');
        } else if (e.key === 'ArrowDown') {
          e.preventDefault();
          this.navigateHistory('down');
        } else if (e.key === 'Tab') {
          e.preventDefault();
          this.handleTabAutocomplete();
        }
      }
    });

    this.closeBtn.addEventListener('click', () => this.close());
    this.overlay.addEventListener('click', (e) => {
      if (e.target === this.overlay) this.close();
    });

    this.form.addEventListener('submit', (e) => {
      e.preventDefault();
      const cmd = this.input.value.trim();
      if (cmd) {
        this.commandHistory.push(cmd);
        this.historyIndex = this.commandHistory.length;
        this.executeCommand(cmd);
        this.input.value = '';
      }
    });

    this.body.addEventListener('click', () => {
      this.input.focus();
    });
  }

  toggle() {
    if (this.isOpen) {
      this.close();
    } else {
      this.open();
    }
  }

  open() {
    this.isOpen = true;
    this.overlay.classList.add('active');
    this.overlay.setAttribute('aria-hidden', 'false');
    setTimeout(() => this.input.focus(), 100);
    this.scrollToBottom();
  }

  close() {
    this.isOpen = false;
    this.overlay.classList.remove('active');
    this.overlay.setAttribute('aria-hidden', 'true');
  }

  scrollToBottom() {
    this.body.scrollTop = this.body.scrollHeight;
  }

  print(htmlContent, className = '') {
    const line = document.createElement('div');
    line.className = `term-line ${className}`;
    line.innerHTML = htmlContent;
    this.body.appendChild(line);
    this.scrollToBottom();
  }

  initCommands() {
    this.commands = {
      help: {
        description: 'Muestra la lista de comandos disponibles.',
        action: () => {
          this.print('Comandos disponibles en <span class="term-output-info">v1r3-sh</span>:', 'term-output-success');
          const maxLen = Math.max(...Object.keys(this.commands).map(k => k.length));
          for (const [name, data] of Object.entries(this.commands)) {
            const padding = ' '.repeat(maxLen - name.length + 2);
            this.print(`  <span class="term-output-success">${name}</span>${padding} - ${data.description}`);
          }
        }
      },
      about: {
        description: 'Resumen rápido del perfil profesional.',
        action: () => {
          this.print(`=== VICTOR | FULL-STACK & CYBERSECURITY ARCHITECT ===`, 'term-output-info');
          this.print('Ingeniero de Software especializado en crear experiencias web inmersivas,');
          this.print('sistemas modulares limpios y arquitectura segura (Security-first mindset).');
          this.print('Stack principal: TypeScript, Node.js, React/Vue, Python, Docker, Linux, Pentesting.');
        }
      },
      skills: {
        description: 'Lista el stack tecnológico agrupado por categorías.',
        action: () => {
          this.print('--- SKILLS & TECH STACK ---', 'term-output-info');
          this.print(' [████████████████████] 100% Full-Stack Architecture (TS, Node, React, Express)');
          this.print(' [█████████████████   ] 85%  Cybersecurity & Pentesting (OWASP, Burp, Linux hardening)');
          this.print(' [██████████████████  ] 90%  DevOps & Cloud (Docker, CI/CD, Nginx, AWS)');
          this.print(' [████████████████    ] 80%  Database & Storage (PostgreSQL, Redis, MongoDB)');
        }
      },
      projects: {
        description: 'Muestra los proyectos destacados y repositorios.',
        action: () => {
          this.print('--- PROYECTOS DESTACADOS ---', 'term-output-info');
          this.print('1. <a href="https://github.com" target="_blank" class="term-output-success">V1R3.DEV Portfolio</a> - OS-themed immersive portfolio with BIOS & arcade games.');
          this.print('2. <a href="https://github.com" target="_blank" class="term-output-success">SecAudit CLI</a> - Automated vulnerability scanner for web microservices.');
          this.print('3. <a href="https://github.com" target="_blank" class="term-output-success">CloudShield Auth</a> - Zero-trust authentication microservice.');
        }
      },
      scan: {
        description: 'Ejecuta un escaneo de vulnerabilidades simulado del portfolio.',
        action: () => {
          this.print('[*] Iniciando auditoría de seguridad en vivo sobre v1r3.dev...', 'term-output-info');
          setTimeout(() => this.print('[+] Verificando cabeceras HTTP (CSP, HSTS, X-Frame-Options)... OK'), 500);
          setTimeout(() => this.print('[+] Comprobando inyección SQL & XSS en formularios... 0 vulnerabilidades detectadas'), 1100);
          setTimeout(() => this.print('[+] Analizando dependencias NPM y módulos ES... 100% seguros'), 1700);
          setTimeout(() => {
            this.print('========================================', 'term-output-success');
            this.print('[✔] ESCANEO FINALIZADO: SISTEMA 100% SEGURO Y OPTIMIZADO.', 'term-output-success');
            this.print('========================================', 'term-output-success');
          }, 2200);
        }
      },
      matrix: {
        description: 'Activa o desactiva el modo lluvia de código Matrix.',
        action: () => {
          if (this.matrixActive) {
            this.stopMatrix();
            this.print('[-] Modo Matrix desactivado.', 'term-output-warn');
          } else {
            this.startMatrix();
            this.print('[+] Modo Matrix activado. ¡Despierta, Neo!', 'term-output-success');
          }
        }
      },
      contact: {
        description: 'Copia el email al portapapeles y muestra opciones.',
        action: () => {
          const email = 'victor@v1r3.dev';
          navigator.clipboard.writeText(email).then(() => {
            this.print(`[+] Email <span class="term-output-success">${email}</span> copiado al portapapeles con éxito.`, 'term-output-success');
          }).catch(() => {
            this.print(`[!] Contacto directo: ${email}`, 'term-output-info');
          });
        }
      },
      hire: {
        description: 'Atajo rápido para propuesta laboral.',
        action: () => {
          this.print('Para contratación directa, envía un correo a <a href="mailto:victor@v1r3.dev" class="term-output-success">victor@v1r3.dev</a>', 'term-output-info');
          this.print('O prueba ejecutando el comando: <span class="term-output-success">sudo hire victor</span>');
        }
      },
      sudo: {
        description: 'Ejecuta comandos con privilegios elevados.',
        action: (args) => {
          if (args.join(' ') === 'hire victor') {
            this.print('[!] Privilegios de Administrador concedidos.', 'term-output-success');
            this.print('🎉 ¡LOGRO DESBLOQUEADO: "System Administrator & Tech Recruiter Elite"! 🎉', 'term-output-success');
            this.print('¡Excelente decisión! Victor está listo para aportar un valor excepcional a tu equipo técnico.');
            this.triggerConfetti();
          } else {
            this.print(`sudo: ${args.join(' ')}: comando no reconocido o sin privilegios suficientes.`, 'term-output-error');
          }
        }
      },
      cv: {
        description: 'Descarga directa del CV en PDF.',
        action: () => {
          this.print('[+] Preparando descarga de Vire-CV.pdf...', 'term-output-info');
          setTimeout(() => {
            const link = document.createElement('a');
            link.href = '/assets/cv/Vire-CV.pdf';
            link.download = 'Vire-CV.pdf';
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
            this.print('[✔] ¡CV descargado con éxito!', 'term-output-success');
          }, 800);
        }
      },
      clear: {
        description: 'Limpia la pantalla de la terminal.',
        action: () => {
          this.body.innerHTML = '';
        }
      }
    };
  }

  executeCommand(inputStr) {
    this.print(`<span class="term-output-dim">v1r3@dev:~$</span> ${inputStr}`);
    const parts = inputStr.trim().split(/\s+/);
    const cmdName = parts[0].toLowerCase();
    const args = parts.slice(1);

    if (this.commands[cmdName]) {
      try {
        this.commands[cmdName].action(args);
      } catch (err) {
        this.print(`Error ejecutando '${cmdName}': ${err.message}`, 'term-output-error');
      }
    } else {
      this.print(`zsh: comando no encontrado: ${cmdName}. Escribe "help" para ver la ayuda.`, 'term-output-error');
    }
  }

  navigateHistory(direction) {
    if (this.commandHistory.length === 0) return;
    if (direction === 'up') {
      if (this.historyIndex > 0) this.historyIndex--;
    } else if (direction === 'down') {
      if (this.historyIndex < this.commandHistory.length - 1) {
        this.historyIndex++;
      } else {
        this.historyIndex = this.commandHistory.length;
        this.input.value = '';
        return;
      }
    }
    if (this.commandHistory[this.historyIndex] !== undefined) {
      this.input.value = this.commandHistory[this.historyIndex];
    }
  }

  handleTabAutocomplete() {
    const val = this.input.value.trim().toLowerCase();
    if (!val) return;
    const matches = Object.keys(this.commands).filter(c => c.startsWith(val));
    if (matches.length === 1) {
      this.input.value = matches[0];
    } else if (matches.length > 1) {
      this.print(`<span class="term-output-dim">v1r3@dev:~$</span> ${this.input.value}`);
      this.print(`Sugerencias: ${matches.join(', ')}`, 'term-output-info');
    }
  }

  startMatrix() {
    if (this.matrixActive) return;
    this.matrixActive = true;

    const canvas = document.createElement('canvas');
    canvas.id = 'matrixCanvas';
    canvas.style.position = 'fixed';
    canvas.style.top = '0';
    canvas.style.left = '0';
    canvas.style.width = '100vw';
    canvas.style.height = '100vh';
    canvas.style.zIndex = '9999';
    canvas.style.pointerEvents = 'none';
    canvas.style.opacity = '0.35';
    document.body.appendChild(canvas);

    const ctx = canvas.getContext('2d');
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;

    const chars = '01ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789@#$%&';
    const fontSize = 16;
    const columns = canvas.width / fontSize;
    const drops = [];
    for (let i = 0; i < columns; i++) drops[i] = 1;

    this.matrixInterval = setInterval(() => {
      ctx.fillStyle = 'rgba(0, 0, 0, 0.05)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#00ff66';
      ctx.font = `${fontSize}px monospace`;

      for (let i = 0; i < drops.length; i++) {
        const text = chars.charAt(Math.floor(Math.random() * chars.length));
        ctx.fillText(text, i * fontSize, drops[i] * fontSize);
        if (drops[i] * fontSize > canvas.height && Math.random() > 0.975) {
          drops[i] = 0;
        }
        drops[i]++;
      }
    }, 33);
  }

  stopMatrix() {
    this.matrixActive = false;
    if (this.matrixInterval) clearInterval(this.matrixInterval);
    const canvas = document.getElementById('matrixCanvas');
    if (canvas) canvas.remove();
  }

  triggerConfetti() {
    for (let i = 0; i < 30; i++) {
      const conf = document.createElement('div');
      conf.style.position = 'fixed';
      conf.style.left = `${Math.random() * 100}vw`;
      conf.style.top = `-20px`;
      conf.style.width = '8px';
      conf.style.height = '8px';
      conf.style.backgroundColor = ['#00ff66', '#ffbd2e', '#ff5f56', '#00d2ff'][Math.floor(Math.random() * 4)];
      conf.style.zIndex = '100000';
      conf.style.borderRadius = '50%';
      conf.style.transition = `all ${1 + Math.random() * 2}s ease-out`;
      document.body.appendChild(conf);

      setTimeout(() => {
        conf.style.top = `${100 + Math.random() * 20}vh`;
        conf.style.transform = `translateX(${(Math.random() - 0.5) * 200}px) rotate(${Math.random() * 360}deg)`;
        conf.style.opacity = '0';
      }, 50);

      setTimeout(() => conf.remove(), 3000);
    }
  }
}

document.addEventListener('DOMContentLoaded', () => {
  window.v1r3Terminal = new TerminalCLI();
});
```

